    // SAFE MODE: Copy a standalone helper file instead of adding file: dependency.
    // file: deps break in Lovable, Vercel, and all CI/CD environments.
    const helperContent = `/**
 * Claude Hub Agent Helper — auto-generated by Claude Hub install-sdk
 * Calls Claude Hub agents via HTTP. No npm dependency required.
 * Claude Hub must be running at localhost:3847 (auto-starts on login).
 *
 * Usage (browser/Vite):
 *   import { callAgent, isOnline } from '@/lib/claudeHub'
 *   const result = await callAgent('quill', 'Write a tagline')
 *
 * NOTE: Only works during local development. Claude Hub is not available
 * in production/deployed environments (Lovable, Vercel, etc.).
 */

const CLAUDE_HUB_URL = import.meta.env.VITE_CLAUDE_HUB_URL || 'http://localhost:3847'

export async function callAgent(agentName, prompt, timeoutMs = 120000) {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), timeoutMs)

  try {
    const response = await fetch(\`\${CLAUDE_HUB_URL}/api/playground/run\`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentName, prompt }),
      signal: controller.signal,
    })
    clearTimeout(timeout)
    if (!response.ok) throw new Error(\`Claude Hub returned \${response.status}\`)

    const text = await response.text()
    const events = text
      .split('\\n')
      .filter(line => line.startsWith('data: '))
      .map(line => { try { return JSON.parse(line.slice(6)) } catch { return null } })
      .filter(Boolean)

    const errorEvent = events.find(e => e.type === 'error')
    if (errorEvent) return { success: false, output: '', agent: agentName, error: errorEvent.error }

    const doneEvent = events.find(e => e.type === 'done' || e.type === 'complete')
    return { success: true, output: doneEvent?.output || '', agent: agentName }
  } catch (err) {
    clearTimeout(timeout)
    const msg = err instanceof Error ? err.message : String(err)
    return {
      success: false,
      output: '',
      agent: agentName,
      error: msg.includes('abort')
        ? \`Timed out after \${timeoutMs / 1000}s\`
        : \`Claude Hub not reachable — is it running?\`,
    }
  }
}

export async function listAgents() {
  try {
    const res = await fetch(\`\${CLAUDE_HUB_URL}/api/global/agents\`)
    if (!res.ok) throw new Error(\`HTTP \${res.status}\`)
    return await res.json()
  } catch { return [] }
}

